WITH page_agg AS ( SELECT wp.wp_web_page_id, wp.wp_type, wp.wp_url, SUM(wr.wr_return_amt) AS total_return_amt, SUM(wr.wr_return_quantity) AS total_return_qty, COUNT(DISTINCT wr.wr_order_number) AS distinct_orders, COUNT(*) AS total_returns, SUM(COALESCE(p.p_cost,0)) AS total_promo_cost, AVG(COALESCE(p.p_cost,0)) AS avg_promo_cost, COUNT(DISTINCT p.p_promo_id) AS distinct_promos FROM web_page wp JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk JOIN item i ON i.i_item_sk = wr.wr_item_sk LEFT JOIN promotion p ON p.p_item_sk = i.i_item_sk GROUP BY wp.wp_web_page_id, wp.wp_type, wp.wp_url ) SELECT wp_web_page_id, wp_type, wp_url, total_return_amt, total_return_qty, total_returns, distinct_orders, total_promo_cost, avg_promo_cost, distinct_promos, CASE WHEN total_return_amt > 20000 THEN 'High Return Volume' WHEN total_return_amt BETWEEN 10000 AND 20000 THEN 'Medium Return Volume' ELSE 'Low Return Volume' END AS return_volume_category, DENSE_RANK() OVER (ORDER BY total_return_amt DESC) AS return_volume_rank, SUM(total_return_amt) OVER (ORDER BY total_return_amt DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amt FROM page_agg ORDER BY return_volume_rank LIMIT 30
